272	  let parsed: unknown;
273	  try {
274	    parsed = JSON.parse(raw);
275	  } catch (err) {
276	    throw new ApiError(
277	      'PARSE_ERROR',
278	      `Failed to parse assignments.json as JSON: ${(err as Error).message}`
279	    );
280	  }
