350	  if (!defaultValidation.success) {
351	    throw new ApiError(
352	      'VALIDATION_ERROR',
353	      `default.json failed schema validation: ${defaultValidation.error.message}`
354	    );
355	  }
356	  const defaults = defaultValidation.data;
357	
358	  // Read local (may not exist yet — start from empty)
359	  let locals: ModelEntry[] = [];
360	  try {
361	    locals = await readModels();
362	  } catch (err) {
363	    // Note: ENOENT on local.json is handled inside readModels() via auto-init from
364	    // default.json — it never reaches here as READ_ERROR.  This catch handles the
365	    // narrow case where readModels() throws READ_ERROR for a non-ENOENT OS error

